  // Banque de questions et thèmes autorisés selon l’élection (type) ; vil = petite commune
  function bankKey(type, vil) { if (type === 'mun') return vil ? 'vil' : 'mun'; if (type === 'dep' || type === 'reg' || type === 'sen' || type === 'euro') return type; if (type === 'leg' || type === 'pres') return 'nat'; return null; }
  function comp(type, vil) { const k = bankKey(type, vil); if (!k || k === 'nat') return null; return COMP[k] || null; }
  const SIDE_NAT = { G: 'g', GE: 'g', C: 'c', D: 'd', ED: 'ed', DIV: 'c' };
  function natLine(bloc, th) { const T = TH_NAT[th]; if (!T) return null; return T[SIDE_NAT[bloc] || 'c'] || T.d || T.c; }
  return { GEN, VS, SAME, METIER, SIT, EL, PROP, RUMEURS, PROM, COMP, Q, VALQ, TH_NAT, OPPL, JABS, BLUFF, CITIZEN, EV_META, EVENTS, gtxt, fill, attack, rumeur, promesse, bankKey, comp, natLine };

